 الكاملة","en":"Capturing the complete Binghatti inventory"},{"do":"save_json","key":"units","selector":"[data-available-units-url]","attr":"data-available-units-url","items_path":"data.items","total_path":"data.totalCount","page_no_path":"data.pageNo","page_size_path":"data.pageSize","page_param":"pageNo","page_size_param":"pageSize","page_size":1000,"id_key":"id","max_pages":50}]$recipe$::text,
